create table if not exists public.medication_catalog_versions(id uuid primary key default gen_random_uuid(),version text not null unique,source_name text not null,source_url text,effective_from timestamptz,effective_to timestamptz,source_hash text,status text not null default 'draft' check(status in('draft','published','superseded','rejected')),imported_at timestamptz not null default now(),published_at timestamptz,created_by uuid references auth.users(id));
create table if not exists public.medication_catalog(id uuid primary key default gen_random_uuid(),catalog_version_id uuid not null references public.medication_catalog_versions(id) on delete cascade,external_code text,name text not null,active_ingredient text,strength text,pharmaceutical_form text,pack_description text,manufacturer text,marketing_status text not null default 'unknown',pph_mad numeric(12,2),hospital_price_mad numeric(12,2),effective_from timestamptz,effective_to timestamptz,source_reference text,created_at timestamptz not null default now());
create unique index if not exists medication_catalog_version_code_uq on public.medication_catalog(catalog_version_id,external_code) where external_code is not null;
create index if not exists medication_catalog_name_idx on public.medication_catalog using gin(to_tsvector('simple',name));
create index if not exists medication_catalog_ingredient_idx on public.medication_catalog using gin(to_tsvector('simple',coalesce(active_ingredient,'')));
alter table public.medication_catalog_versions enable row level security; alter table public.medication_catalog enable row level security;
drop policy if exists medication_catalog_public_published on public.medication_catalog; create policy medication_catalog_public_published on public.medication_catalog for select to anon,authenticated using(exists(select 1 from public.medication_catalog_versions v where v.id=catalog_version_id and v.status='published'));
drop policy if exists medication_catalog_versions_public_published on public.medication_catalog_versions; create policy medication_catalog_versions_public_published on public.medication_catalog_versions for select to anon,authenticated using(status='published');
